channel_event_v1115:
"""v1.10.15 频道事件驱动 + 7 天资源缓存 + 观影独立轮询。

运行语义：
- Telegram/频道仍按既有游标每 5 分钟增量刷新，但只有“本轮真正新增”的消息才触发订阅匹配；
- 新频道消息先做标题/TMDB/季与显式集号的轻量匹配，只把可能覆盖当前缺集的订阅送进执行链；
- 频道 ResourceGroup/分享链接进入 7 天本地缓存，新订阅直接查缓存，不为单个订阅重复刷新频道；
- 频道事件批次禁止访问观影/迅雷外部搜索，不消耗观影轮询冷却；
- 观影保持独立定时轮询，只处理仍有缺集且达到外部检索冷却时间的订阅；
- 同一 tick 若频道命中订阅，频道优先，观影最多顺延一个 tick，避免刚命中频道又重复搜索站点；
- 周期批次仍复用可靠后台队列，执行中重复事件继续由 v1.10.14 去自激层合并。

v1.12.5 的最终调度层会把常规观影轮询收口到 AiringDue；本层保留旧 ABI，并把来源 mode
改成 thread-local 真相，避免频道 worker 与日历/人工线程并发时互相误读 channel_event。
"""

from __future__ import annotations

import hashlib
import threading
import time
from typing import Any, Dict, Iterable, List, Tuple

from .episode_resolver_v190 import reliable_episode_set, resolve_episode
from .legacy import _entry_match_reason
from .xunlei_final_v1114 import GuangYaXunleiFinalV1114Mixin


_CHANNEL_CACHE_KEY_V1115 = "channel_resource_cache_v1115"
_CHANNEL_CACHE_RETENTION_SECONDS_V1115 = 7 * 24 * 60 * 60
_CHANNEL_CACHE_CLEANUP_SECONDS_V1115 = 7 * 24 * 60 * 60
_CHANNEL_CACHE_MAX_ITEMS_V1115 = 5000


def _entry_key_v1115(entry: Dict[str, Any]) -> str:
    """频道资源稳定键：新消息即使复用旧分享也必须得到新键。"""
    row = dict(entry or {})
    source = str(row.get("source_url") or row.get("source_label") or "").strip()
    message_id = str(row.get("message_id") or "").strip()
    resource_group_id = str(row.get("resource_group_id") or "").strip()
    share = str(row.get("share_url") or "").strip()
    external = []
    for item in row.get("external_sources") or []:
        if not isinstance(item, dict):
            continue
        external.append(
            f"{str(item.get('type') or '').strip()}:{str(item.get('identity') or item.get('uri') or '').strip()}"
        )
    external.sort()
    if resource_group_id:
        marker = f"rg:{resource_group_id}"
    elif message_id:
        marker = f"msg:{message_id}|share:{share}|ext:{'|'.join(external)}"
    else:
        marker = f"share:{share}|ext:{'|'.join(external)}|title:{str(row.get('display_title') or '')}"
    if not marker.strip("|:"):
        return ""
    return hashlib.sha256(f"{source}|{marker}".encode("utf-8")).hexdigest()


class GuangYaChannelEventV1115Mixin(GuangYaXunleiFinalV1114Mixin):
    """把频道发现与观影轮询拆成两套触发模型。"""

    build_id = "20260902-r26"

    def init_plugin(self, config: dict = None) -> None:
        self._route_source_mode_v1115 = ""
        self._route_source_local_v1115 = threading.local()
        self._channel_new_entries_v1115: List[Dict[str, Any]] = []
        return super().init_plugin(config)

    def _route_source_mode_value_v1115(self) -> str:
        """当前线程的来源模式是真相；共享字段只在 thread-local 尚未初始化时兼容旧入口。"""
        local = getattr(self, "_route_source_local_v1115", None)
        if local is not None:
            # 关键并发语义：thread-local 已存在时，本线程没有 mode 就必须视为空模式，
            # 绝不能回退到另一个线程刚写入的共享兼容字段。
            return str(getattr(local, "mode", "") or "")
        return str(getattr(self, "_route_source_mode_v1115", "") or "")

    # ------------------------------------------------------------------
    # 7 天频道资源缓存
    # ------------------------------------------------------------------
    def _channel_cache_v1115(self) -> Dict[str, Any]:
        raw = self.get_data(_CHANNEL_CACHE_KEY_V1115) or {}
        if not isinstance(raw, dict):
            raw = {}
        items = raw.get("items")
        if not isinstance(items, dict):
            items = {}
        return {
            "items": dict(items),
            "last_cleanup_at": float(raw.get("last_cleanup_at") or 0),
            "updated_at": float(raw.get("updated_at") or 0),
        }

    def _save_channel_cache_v1115(self, cache: Dict[str, Any]) -> None:
        self.save_data(_CHANNEL_CACHE_KEY_V1115, cache)

    def _refresh_channel_cache_v1115(self, rows: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
        cache = self._channel_cache_v1115()
        items = dict(cache.get("items") or {})
        now = time.time()
        had_cache = bool(items)
        new_rows: List[Dict[str, Any]] = []

        for raw in rows or []:
            if not isinstance(raw, dict) or raw.get("stale"):
                continue
            entry = dict(raw)
            key = _entry_key_v1115(entry)
            if not key:
                continue
            previous = dict(items.get(key) or {})
            added_at = float(previous.get("cache_added_at") or 0) or now
            entry["cache_key_v1115"] = key
            entry["cache_added_at"] = added_at
            entry["cache_seen_at"] = now
            # 首次从旧 channel_index 建缓存只作为 bootstrap，不把整个频道历史误当新消息。
            if had_cache and not previous and not entry.get("cached_index"):
                new_rows.append(dict(entry))
            items[key] = entry

        last_cleanup = float(cache.get("last_cleanup_at") or 0)
        if not last_cleanup or now - last_cleanup >= _CHANNEL_CACHE_CLEANUP_SECONDS_V1115:
            cutoff = now - _CHANNEL_CACHE_RETENTION_SECONDS_V1115
            items = {
                key: row for key, row in items.items()
                if float((row or {}).get("cache_added_at") or now) >= cutoff
            }
            last_cleanup = now

        if len(items) > _CHANNEL_CACHE_MAX_ITEMS_V1115:
            ordered = sorted(
                items.items(),
                key=lambda pair: float((pair[1] or {}).get("cache_added_at") or 0),
                reverse=True,
            )[:_CHANNEL_CACHE_MAX_ITEMS_V1115]
            items = dict(ordered)

        self._save_channel_cache_v1115({
            "items": items,
            "last_cleanup_at": last_cleanup,
            "updated_at": now,
            "retention_days": 7,
        })
        return new_rows

    def _channel_cache_rows_v1115(self) -> List[Dict[str, Any]]:
        cache = self._channel_cache_v1115()
        rows = [dict(row) for row in (cache.get("items") or {}).values() if isinstance(row, dict)]
        rows.sort(key=lambda row: float(row.get("cache_added_at") or 0), reverse=True)
        return rows

    def _hydrate_channel_index_for_subscription_v1115(self, subscribe: Any) -> int:
        """只把当前订阅相关的 7 天缓存补回 channel_index，供成熟分享/ResourcePlanner 复用。"""
        index = dict(self.get_data("channel_index") or {})
        current = list(index.get("items") or [])
        seen = {_entry_key_v1115(row) for row in current if isinstance(row, dict)}
        added = 0
        for row in self._channel_cache_rows_v1115():
            key = _entry_key_v1115(row)
            if not key or key in seen:
                continue
            try:
                matched, _ = _entry_match_reason(row, subscribe)
            except Exception:
                matched = False
            if not matched:
                continue
            restored = dict(row)
            restored["stale"] = False
            restored["cached_index"] = True
            current.append(restored)
            seen.add(key)
            added += 1
        if added:
            index["items"] = current
            index["cache_retention_days"] = 7
            self.save_data("channel_index", index)
        return added

    def _cached_matches_for_subscription(self, subscribe: Any):
        pairs = list(super()._cached_matches_for_subscription(subscribe) or [])
        seen = {_entry_key_v1115(row) for row, _ in pairs if isinstance(row, dict)}
        for row in self._channel_cache_rows_v1115():
            key = _entry_key_v1115(row)
            if not key or key in seen:
                continue
            try:
                matched, reason = _entry_match_reason(row, subscribe)
            except Exception:
                continue
            if matched:
                pairs.append((row, reason))
                seen.add(key)
        return pairs

    def refresh_channels(self, force: bool = False):
        # 主动 Pull 内部若旧层因为“无频道命中”要求 refresh，只允许读缓存，不再额外访问频道。
        if self._route_source_mode_value_v1115() in {"viewing_poll", "airing_pull", "daily_repair_pull"} and not force:
            return list((self.get_data("channel_index") or {}).get("items") or [])
        rows = list(super().refresh_channels(force=force) or [])
        self._channel_new_entries_v1115 = self._refresh_channel_cache_v1115(rows)
        return rows

    # ------------------------------------------------------------------
    # 新频道消息 -> 只匹配可能缺集的订阅
    # ------------------------------------------------------------------
    def _entry_can_cover_missing_v1115(self, entry: Dict[str, Any], subscribe: Any) -> bool:
        if self._is_movie_subscription(subscribe):
            return True
        missing = {
            int(value) for value in (self._subscription_missing_episodes(subscribe) or [])
            if int(value or 0) > 0
        }
        if not missing:
            return False
        hint = str(entry.get("episode_hint") or "").strip()
        if not hint:
            return True
        try:
            result = resolve_episode(hint, season_hint=getattr(subscribe, "season", None))
            explicit = reliable_episode_set(result, 0.99)
        except Exception:
            explicit = set()
        # 有明确集号时先本地判断交集；没有明确集号交给后续分享文件解析。
        return not explicit or bool(explicit.intersection(missing))

    def _subscriptions_for_new_channel_entries_v1115(self) -> List[int]:
        entries = list(getattr(self, "_channel_new_entries_v1115", []) or [])
        if not entries:
            return []
        selected = {
            int(value) for value in self._selected_subscriptions
            if str(value).isdigit() and int(value) > 0
        }
        matched_ids = set()
        for subscribe in self._list_subscriptions("N,R"):
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid not in selected or not self._is_guangya_route(subscribe):
                continue
            for entry in entries:
                try:
                    matched, _ = _entry_match_reason(entry, subscribe)
                except Exception:
                    matched = False
                if not matched:
                    continue
                if not self._entry_can_cover_missing_v1115(entry, subscribe):
                    continue
                matched_ids.add(sid)
                break
        return sorted(matched_ids)

    # ------------------------------------------------------------------
    # 频道批次不碰观影；主动 Pull 的冷却由上层统一调度
    # ------------------------------------------------------------------
    def _claim_external_search_round_v1114(self, subscribe: Any, force: bool = False) -> bool:
        if self._route_source_mode_value_v1115() == "channel_event":
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid > 0:
                self._external_round_allowed_v1114[sid] = False
            return False
        return super()._claim_external_search_round_v1114(subscribe, force=force)

    def _viewing_due_subscription_ids_v1115(self) -> List[int]:
        state = self._external_search_state_v1114()
        now = time.time()
        cooldown = max(900, int(self._external_search_cooldown_minutes_v1114) * 60)
        selected = {
            int(value) for value in self._selected_subscriptions
            if str(value).isdigit() and int(value) > 0
        }
        due: List[int] = []
        for subscribe in self._list_subscriptions("N,R"):
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid not in selected or not self._is_guangya_route(subscribe):
                continue
            if not self._is_movie_subscription(subscribe):
                missing = list(self._subscription_missing_episodes(subscribe) or [])
                if not missing:
                    self._finish_subscription_if_complete(subscribe)
                    continue
            row = dict(state.get(str(sid)) or {})
            try:
                last_at = float(row.get("last_at") or 0)
            except (TypeError, ValueError):
                last_at = 0.0
            if not last_at or now - last_at >= cooldown:
                due.append(sid)
        return due

    def _run_v1115_mode_batch(self, batch: List[int], trigger: str, mode: str, force: bool = False) -> None:
        local = getattr(self, "_route_source_local_v1115", None)
        if local is None:
            local = threading.local()
            self._route_source_local_v1115 = local
        had_local = hasattr(local, "mode")
        previous_local = str(getattr(local, "mode", "") or "")
        previous = str(getattr(self, "_route_source_mode_v1115", "") or "")
        local.mode = mode
        # 共享字段继续写入，兼容旧诊断；业务判断统一读取 thread-local helper。
        self._route_source_mode_v1115 = mode
        try:
            try:
                self._inspect_cache.clear()
            except Exception:
                pass
            for sid in batch:
                if not self._runtime_is_current() or not self._enabled:
                    return
                subscribe = self._find_subscription(int(sid or 0))
                if not subscribe or not self._is_guangya_route(subscribe):
                    continue
                if str(mode or "") == "airing_pull":
                    self._plugin_log(
                        "INFO",
                        "【主动检索派发】sid=%s media=%s mode=airing_pull trigger=%s force=%s",
                        int(sid or 0),
                        str(getattr(subscribe, "name", "") or "")[:120] or "-",
                        str(trigger or "-")[:80],
                        bool(force),
                    )
                self._hydrate_channel_index_for_subscription_v1115(subscribe)
                try:
                    result = self._try_transfer_subscription(
                        subscribe,
                        force=bool(force),
                        refresh_channel=False,
                    )
                    message = str((result or {}).get("message") or "检查完成")
                    self._record_route_health(
                        last_route_result=message[:500],
                        last_route_result_at=self._now_text(),
                        last_async_check_id=int(sid),
                        last_async_trigger=trigger,
                        last_source_mode=mode,
                    )
                    self._plugin_log(
                        "INFO",
                        "【光鸭转存助手】【来源调度】#%s %s mode=%s：%s",
                        sid,
                        getattr(subscribe, "name", ""),
                        mode,
                        message,
                    )
                except Exception as err:
                    self._plugin_log(
                        "EXCEPTION",
                        "【光鸭转存助手】【来源调度】#%s %s mode=%s 异常：%s",
                        sid,
                        getattr(subscribe, "name", ""),
                        mode,
                        err,
                    )
        finally:
            if had_local:
                local.mode = previous_local
            else:
                try:
                    delattr(local, "mode")
                except AttributeError:
                    pass
            self._route_source_mode_v1115 = previous

    def _run_reliability_route_batch(self, batch: List[int], trigger: str) -> None:
        text = str(trigger or "")
        if "频道新增资源" in text:
            return self._run_v1115_mode_batch(batch, trigger, "channel_event", force=False)
        if "观影定时轮询" in text:
            return self._run_v1115_mode_batch(batch, trigger, "viewing_poll", force=False)
        if "新订阅资源匹配" in text:
            return self._run_v1115_mode_batch(batch, trigger, "subscription_prime", force=True)
        return super()._run_reliability_route_batch(batch, trigger)

    # ------------------------------------------------------------------
    # tick：旧实现保留 ABI；v1.12.5 最外层会在 tick 线程内抑制 viewing_ids。
    # ------------------------------------------------------------------
    def _tick(self, host_service: bool = True) -> None:
        if not self._runtime_is_current() or not self._enabled:
            return
        if host_service:
            self._host_tick_heartbeat = time.monotonic()
            self._plugin_log("INFO", "【光鸭转存助手】【服务】宿主定时服务心跳已确认")
        self._install_takeover()
        self.refresh_channels(force=False)

        channel_ids = self._subscriptions_for_new_channel_entries_v1115()
        if channel_ids:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【频道事件】本轮新增频道资源命中 %s 个订阅；只处理命中项，观影轮询顺延到下一 tick",
                len(channel_ids),
            )
            self._queue_async_route_check(channel_ids, trigger="频道新增资源")
            return

        viewing_ids = self._viewing_due_subscription_ids_v1115()
        if viewing_ids:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【观影轮询】%s 个仍缺资源的订阅达到搜索冷却时间，进入独立观影轮询",
                len(viewing_ids),
            )
            self._queue_async_route_check(viewing_ids, trigger="观影定时轮询")

    def _startup_check(self) -> None:
        # 启动不再全量消费旧频道索引；按一次普通 tick 恢复频道游标与到期观影轮询即可。
        if not self._runtime_is_current() or not self._enabled:
            return
        return self._tick(host_service=False)

    def _spawn_route_prime(self, sids: Iterable[int], trigger: str = "立即检查") -> None:
        ids = sorted({
            int(value) for value in sids
            if str(value).isdigit() and int(value) > 0
        })
        if not ids or not self._enabled:
            return
        # 新订阅先查 7 天缓存；不为单个订阅强刷频道。force=True 只用于本轮观影立即搜索。
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【新订阅】%s 个订阅先匹配 7 天频道缓存；未覆盖部分再立即搜索观影，不单独刷新频道",
            len(ids),
        )
        self._queue_async_route_check(ids, trigger="新订阅资源匹配")


__all__ = ["GuangYaChannelEventV1115Mixin"]

channel_reconcile_v11215:
"""v1.12.15：频道缓存被动补偿 + 新订阅频道预热。

严格频道游标只回答“这一轮是不是新消息”，7 天频道缓存回答“资源现在是否已经存在”。
旧实现只把严格新消息送入 channel_event，因此在首次建立游标、插件重启/bootstrap、
或事件触发被后台合并等情况下，会出现“频道缓存明明已有可用资源，但已有订阅没有再进入转存”的空窗。

另一个实机空窗发生在“资源先发、订阅后加”：新增订阅过去虽然会在本地缓存未命中时
``refresh_channels(force=True)``，但底层刷新仍受 Telegram message cursor 约束；如果目标资源
位于当前游标之前、又从未进入 7 天缓存，强刷也可能只得到游标之后/当前页资源，最终误表现为
“本地频道没有”。v1.12.15 因此把新增订阅顺序收口为：

1. 先强刷全部配置频道，把本轮可见资源写入 7 天 cache；
2. 再匹配刚新增的订阅；
3. 若仍未命中且频道刷新健康，则按现有 ``_history_pages`` 对配置频道做一次有界历史回溯，
   复用现有频道解析器并把回溯结果写入 7 天 cache；
4. 历史回溯只补 cache，不推进/回退 ``channel_cursors``，也不把旧消息伪造成新事件；
5. 完成预热后才把新增订阅送入既有 ``subscription_prime`` 执行链。

本层不把频道变成主动资源站搜索器。所有频道命中仍服从以下边界：
- 不访问 GYING，不消耗外部检索冷却；
- 不绕过媒体身份、质量、MoviePilot library missing、reservation/source claim；
- 不绕过 v1.12.14 物理文件 episodes ⊆ allowed missing；
- 不改变来源优先级和 Magnet/ED2K 的光鸭 cloudcollection 路线。
"""
from __future__ import annotations

import threading
from typing import Any, Dict, Iterable, List, Set, Tuple

from . import legacy as _legacy_module
from .channel_event_v1115 import _entry_key_v1115
from .core_pipeline_final_v11214 import GuangYaCorePipelineFinalV11214Mixin


class GuangYaChannelReconcileV11215Mixin(GuangYaCorePipelineFinalV11214Mixin):
    """让“频道已有资源”成为可恢复事实，并保证新订阅先预热频道再匹配。"""

    plugin_version = "1.12.15"
    build_id = "20260906-r62"
    _channel_prime_wait_seconds_v11215 = 5.0
    _channel_prime_history_pages_cap_v11215 = 20

    @staticmethod
    def _channel_entry_actionable_v11215(entry: Dict[str, Any]) -> bool:
        row = dict(entry or {})
        if row.get("stale"):
            return False
        if str(row.get("share_url") or "").strip():
            return True
        for raw in row.get("xunlei_sources") or []:
            if not isinstance(raw, dict):
                continue
            if str(raw.get("share_id") or raw.get("identity") or raw.get("uri") or "").strip():
                return True
        for raw in row.get("external_sources") or []:
            if not isinstance(raw, dict):
                continue
            source_type = str(raw.get("type") or "").strip().lower()
            if source_type not in {"magnet", "ed2k", "xunlei"}:
                continue
            if str(raw.get("identity") or raw.get("uri") or "").strip():
                return True
        return False

    def _channel_passive_gap_v11215(self, subscribe: Any) -> Tuple[Any, ...]:
        """仅用于决定要不要进入 channel_event；最终写盘仍由既有硬栅栏决定。"""
        try:
            if self._is_movie_subscription(subscribe):
                return ("movie",) if bool(self._movie_needs_pull_v1125(subscribe)) else tuple()
            values = self._uncovered_missing_v1125(subscribe) or set()
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【频道补偿v1.12.15】#%s %s 读取真实未覆盖缺口失败，补偿触发 fail closed：%s",
                int(getattr(subscribe, "id", 0) or 0),
                str(getattr(subscribe, "name", "") or ""),
                str(err)[:220],
            )
            return tuple()
        result: Set[int] = set()
        for raw in values:
            try:
                value = int(raw or 0)
            except (TypeError, ValueError):
                continue
            if value > 0:
                result.add(value)
        return tuple(sorted(result))

    def _cached_actionable_channel_matches_v11215(self, subscribe: Any) -> List[Dict[str, Any]]:
        matches: List[Dict[str, Any]] = []
        seen: Set[str] = set()
        try:
            pairs: Iterable[Any] = self._cached_matches_for_subscription(subscribe) or []
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【频道补偿v1.12.15】#%s %s 读取频道缓存匹配失败：%s",
                int(getattr(subscribe, "id", 0) or 0),
                str(getattr(subscribe, "name", "") or ""),
                str(err)[:220],
            )
            return []

        for item in pairs:
            if isinstance(item, (tuple, list)) and item:
                raw = item[0]
            else:
                raw = item
            if not isinstance(raw, dict):
                continue
            row = dict(raw)
            if not self._channel_entry_actionable_v11215(row):
                continue
            try:
                if not bool(self._entry_can_cover_missing_v1115(row, subscribe)):
                    continue
            except Exception:
                continue
            key = _entry_key_v1115(row)
            if not key:
                key = str(row.get("resource_group_id") or row.get("message_id") or row.get("share_url") or "").strip()
            if key and key in seen:
                continue
            if key:
                seen.add(key)
            matches.append(row)
        return matches

    @staticmethod
    def _channel_label_v11215(source_url: str) -> str:
        return "光鸭云盘影视热更频道" if "regeng" in str(source_url or "").lower() else "光鸭云盘资源分享频道"

    def _channel_refresh_healthy_v11215(self) -> bool:
        """只有本轮频道抓取明确健康时才追加历史回溯，避免绕过 Reliability 退避。"""
        try:
            outage = dict(self.get_data("channel_outage") or {})
        except Exception:
            outage = {}
        if str(outage.get("state") or "").lower() not in {"", "healthy"}:
            return False
        try:
            last_run = dict(self.get_data("last_run") or {})
        except Exception:
            last_run = {}
        if "success" in last_run and not bool(last_run.get("success")):
            return False
        return True

    def _wait_for_channel_refresh_v11215(self) -> None:
        """若强刷被 Reliability 单飞合并，短等正在进行的刷新结束后再读 cache。"""
        lock = getattr(self, "_channel_refresh_lock", None)
        if lock is None or not getattr(lock, "locked", lambda: False)():
            return
        try:
            acquired = bool(lock.acquire(timeout=float(self._channel_prime_wait_seconds_v11215)))
        except Exception:
            acquired = False
        if acquired:
            try:
                pass
            finally:
                try:
                    lock.release()
                except Exception:
                    pass

    def _history_backfill_for_subscriptions_v11215(self, subscriptions: Iterable[Any]) -> Dict[str, Any]:
        """有界回溯配置频道并只补 7 天 cache；不修改严格事件游标。"""
        pending: Dict[int, Any] = {}
        for subscribe in subscriptions or []:
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid <= 0:
                continue
            if not self._channel_passive_gap_v11215(subscribe):
                continue
            if self._cached_actionable_channel_matches_v11215(subscribe):
                continue
            pending[sid] = subscribe
        if not pending:
            return {"pages": 0, "rows": 0, "cached": 0, "matched_ids": [], "errors": []}

        lock = getattr(self, "_channel_prime_backfill_lock_v11215", None)
        if lock is None:
            lock = threading.Lock()
            self._channel_prime_backfill_lock_v11215 = lock
        if not lock.acquire(blocking=False):
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【新订阅频道预热v1.12.15】已有历史回溯在执行，本批不重复请求；稍后由频道缓存补偿继续匹配",
            )
            return {"pages": 0, "rows": 0, "cached": 0, "matched_ids": [], "errors": ["coalesced"]}

        discovered: List[Dict[str, Any]] = []
        errors: List[str] = []
        matched_ids: Set[int] = set()
        pages_total = 0
        try:
            source_urls = list(self._source_urls() or [])
            page_limit = max(1, int(getattr(self, "_history_pages", 1) or 1))
            page_limit = min(page_limit, max(1, int(self._channel_prime_history_pages_cap_v11215)))
            extractor = getattr(_legacy_module, "_extract_channel_entries", None)
            pager = getattr(_legacy_module, "_extract_pagination_urls", None)
            request_cls = getattr(_legacy_module, "RequestUtils", None)
            settings_obj = getattr(_legacy_module, "settings", None)
            if not callable(extractor) or not callable(pager) or request_cls is None:
                return {"pages": 0, "rows": 0, "cached": 0, "matched_ids": [], "errors": ["channel parser unavailable"]}

            for source_url in source_urls:
                if not pending:
                    break
                queue = [str(source_url)]
                visited: Set[str] = set()
                source_pages = 0
                label = self._channel_label_v11215(str(source_url))
                while queue and source_pages < page_limit and pending:
                    page_url = str(queue.pop(0) or "").strip()
                    if not page_url or page_url in visited:
                        continue
                    visited.add(page_url)
                    try:
                        if bool(getattr(self, "_proxy", False)) and settings_obj is not None:
                            request = request_cls(proxies=getattr(settings_obj, "PROXY", None))
                        else:
                            request = request_cls()
                        response = request.get_res(page_url)
                        status = int(getattr(response, "status_code", 200) or 200) if response is not None else 0
                        if response is None or status >= 400:
                            errors.append(f"{label}: HTTP {status or 'no-response'}")
                            continue
                        page_html = str(getattr(response, "text", "") or "")
                        rows = [dict(row) for row in (extractor(page_html, str(source_url), label) or []) if isinstance(row, dict)]
                    except Exception as err:
                        errors.append(f"{label}: {str(err)[:160]}")
                        continue

                    source_pages += 1
                    pages_total += 1
                    discovered.extend(rows)

                    for sid, subscribe in list(pending.items()):
                        for row in rows:
                            if not self._channel_entry_actionable_v11215(row):
                                continue
                            try:
                                matched, _ = _legacy_module._entry_match_reason(row, subscribe)
                            except Exception:
                                matched = False
                            if not matched:
                                continue
                            try:
                                if not bool(self._entry_can_cover_missing_v1115(row, subscribe)):
                                    continue
                            except Exception:
                                continue
                            matched_ids.add(sid)
                            pending.pop(sid, None)
                            break

                    if pending and source_pages < page_limit:
                        try:
                            next_urls = list(pager(page_html, str(source_url)) or [])
                        except Exception:
                            next_urls = []
                        for next_url in next_urls:
                            value = str(next_url or "").strip()
                            if value and value not in visited and value not in queue and len(queue) < page_limit * 4:
                                queue.append(value)

            before = set()
            try:
                before = set((self._channel_cache_v1115().get("items") or {}).keys())
            except Exception:
                before = set()
            if discovered:
                self._refresh_channel_cache_v1115(discovered)
            after = set()
            try:
                after = set((self._channel_cache_v1115().get("items") or {}).keys())
            except Exception:
                after = before
            cached = max(0, len(after - before))
            return {
                "pages": pages_total,
                "rows": len(discovered),
                "cached": cached,
                "matched_ids": sorted(matched_ids),
                "errors": errors[:8],
            }
        finally:
            lock.release()

    def _spawn_route_prime(self, sids: Iterable[int], trigger: str = "立即检查") -> None:
        """新增订阅必须先拉配置频道、再匹配 cache；必要时回溯游标之前的频道历史。"""
        normalizer = getattr(self, "_positive_ids_v1125", None)
        if callable(normalizer):
            ids = sorted(normalizer(sids or []))
        else:
            ids = sorted({int(value) for value in (sids or []) if str(value).isdigit() and int(value) > 0})
        if not ids or not bool(getattr(self, "_enabled", False)):
            return

        subscriptions: List[Any] = []
        for sid in ids:
            subscribe = self._find_subscription(int(sid or 0))
            if subscribe and self._is_guangya_route(subscribe):
                subscriptions.append(subscribe)
        if not subscriptions:
            return

        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【新订阅频道预热v1.12.15】新增 %s 个固定分流订阅：先强刷全部配置频道，再读取 7 天本地缓存匹配",
            len(subscriptions),
